@startuml

class Employee {
  + Name : string
  + Department : string
  + CardNumber : int
}

class GuestCard {
  + Number : int
  + Date : date
}

class Car {
  + LicensePlate : string
}

class CarPark {
  + IsFull : boolean
}

class Barrier {
  + IsRaised : boolean
}

class CardReader {
  + IsRecognized(cardNumber : int) : boolean
}

class Reception {
  + Collects(card : GuestCard)
}

Employee "1" -- "1" CardReader : uses
Car "1" -- "1" Barrier : triggers
CarPark "1" -- "*" Car : contains
Car "1" -- "1" Barrier : triggers
CarPark "1" -- "1" Barrier : has
CarPark "1" -- "1" Barrier : has
CarPark "1" -- "1" CardReader : has
Reception "1" -- "*" GuestCard : manages

@enduml

